function getCtiExtractor(platform) {
  authorize_();
  return ctiExtractorDelivery_(platform);
}

function ctiExtractorDelivery_(platform) {
  platform = String(platform || '').trim().toLowerCase();
  if (platform !== 'brightspace' && platform !== 'coursera') return {success:false,error:'Unsupported extractor platform: ' + platform};
  var config=platform==='coursera'?CTI_RELEASE_REGISTRY_.courseraExtractor:CTI_RELEASE_REGISTRY_.brightspaceExtractor;
  var script=platform==='coursera'?ctiCanonicalCourseraExtractorSource_():ctiCanonicalBrightspaceExtractorSource_();
  if(script.indexOf(config.version)===-1 || script.indexOf(config.build)===-1) return {success:false,error:'The extractor stored in Code.gs does not match its release label. Replace the complete Code.gs file and update the web-app deployment before copying.'};
  return {success:true,platform:platform.toUpperCase(),name:platform==='coursera'?'CTI Coursera Authoring Evidence Extractor':'CTI Source LMS Ground-Truth Extractor — Brightspace',version:config.version,schemaVersion:config.schema,buildId:config.build,delivery:config.delivery,gatewayRelease:CTI_RELEASE_REGISTRY_.gateway,script:script};
}

// Normalized evidence envelope: adapters may add fields but must not erase provenance.
function ctiEvidenceEnvelope_(platform, kind, identity, payload, provenance) {
  return {
    schemaVersion:CTI_RELEASE_REGISTRY_.evidenceEnvelopeSchema,
    platform:String(platform || '').toUpperCase(),
    kind:String(kind || 'UNKNOWN').toUpperCase(),
    identity:identity && typeof identity === 'object' ? identity : {},
    payload:payload && typeof payload === 'object' ? payload : {},
    provenance:provenance && typeof provenance === 'object' ? provenance : {}
  };
}

