// Security Boundary Guard
function authorize_(requiredRole) {
  var email = String(Session.getActiveUser().getEmail() || "").trim().toLowerCase();
  if (!email) throw new Error("Unauthorized execution attempt.");

  var props = PropertiesService.getScriptProperties();
  var domain = String(props.getProperty("AUTHORIZED_DOMAIN") || "").trim().toLowerCase();
  var emailList = String(props.getProperty("AUTHORIZED_EMAILS") || "")
    .split(",")
    .map(function(value) { return value.trim().toLowerCase(); })
    .filter(String);

  if (domain || emailList.length > 0) {
    var domainMatch = domain && email.slice(-(domain.length + 1)) === "@" + domain;
    var emailMatch = emailList.indexOf(email) > -1;
    if (!domainMatch && !emailMatch) throw new Error("You are not authorized to use this application.");
  }

  if (requiredRole === 'editor') {
    var editorList = String(props.getProperty("EDITOR_EMAILS") || "")
      .split(",")
      .map(function(value) { return value.trim().toLowerCase(); })
      .filter(String);
    if (editorList.length > 0 && editorList.indexOf(email) === -1) throw new Error("You have read-only access to this application.");
  }

  return email;
}

function registerWorkflowFileId_(fileId) {
  var props = PropertiesService.getUserProperties();
  var ids = [];
  try { ids = JSON.parse(props.getProperty('ACTIVE_MASTER_FILE_IDS') || '[]'); } catch (e) {}
  ids = ids.filter(function(id) { return id !== fileId; });
  ids.unshift(fileId);
  props.setProperty('ACTIVE_MASTER_FILE_IDS', JSON.stringify(ids.slice(0, 5)));
}

function validateWorkflowFileId_(fileId) {
  var ids = [];
  try { ids = JSON.parse(PropertiesService.getUserProperties().getProperty('ACTIVE_MASTER_FILE_IDS') || '[]'); } catch (e) {}
  if (ids.indexOf(String(fileId || '')) === -1) throw new Error('This Master workbook is not registered to your active workflow. Upload it again.');
  return fileId;
}

var VALID_STATUSES_ = ["In Queue", "In Progress", "QA Review", "Blocked", "Completed"];

function validateDateOnly_(value, fieldName) {
  var text = String(value || "").trim();
  if (text && !/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    throw new Error(fieldName + " must use YYYY-MM-DD format.");
  }
  return text;
}

function validateStatus_(value) {
  var status = String(value || "In Queue").trim();
  if (VALID_STATUSES_.indexOf(status) === -1) throw new Error("Invalid status value.");
  return status;
}

function validateDriveLink_(value) {
  var link = String(value || "").trim();
  if (!link) return "";
  if (!/^https:\/\/(drive|docs)\.google\.com\//i.test(link)) {
    throw new Error("Drive Link must be an HTTPS Google Drive or Google Docs URL.");
  }
  return link;
}

function validateUuid_(value) {
  var uuid = String(value || "").trim();
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(uuid)) {
    throw new Error("Invalid package UUID.");
  }
  return uuid;
}

function nonNegativeInteger_(value) {
  var number = Number(value);
  return Number.isFinite(number) && number >= 0 ? Math.floor(number) : 0;
}

function versionToken_(value) {
  if (Object.prototype.toString.call(value) === '[object Date]') return String(value.getTime());
  var parsed = new Date(value).getTime();
  return Number.isFinite(parsed) ? String(parsed) : String(value || '');
}

function assertCurrentVersion_(timestampValue, expectedVersion) {
  if (expectedVersion && versionToken_(timestampValue) !== String(expectedVersion)) {
    throw new Error('This record changed after the dashboard loaded. Refresh and try again.');
  }
}

function sheetSafeText_(value) {
  var text = String(value == null ? "" : value);
  return /^[=+\-@]/.test(text) ? "'" + text : text;
}

function normalizeFileName_(fileName, removeDownloadSuffix) {
  var name = String(fileName || "").trim().replace(/\s+/g, " ");
  var dotIndex = name.lastIndexOf(".");
  var extension = dotIndex > 0 ? name.slice(dotIndex).toLowerCase() : "";
  var stem = dotIndex > 0 ? name.slice(0, dotIndex) : name;

  if (removeDownloadSuffix) {
    var previous;
    do {
      previous = stem;
      stem = stem.replace(/\s*\(\d+\)\s*$/, "").trim();
    } while (stem !== previous);
  }

  return (stem + extension).toLowerCase();
}

// Display-safe canonical filename used by duplicate planning.
// Mirrors the browser's removeDownloadSuffix() behavior but preserves case.
// Example: "Course (2).imscc" -> "Course.imscc".
function canonicalDisplayFileName_(fileName) {
  var name = String(fileName || "").trim().replace(/\s+/g, " ");
  var dotIndex = name.lastIndexOf(".");
  var extension = dotIndex > 0 ? name.slice(dotIndex) : "";
  var stem = dotIndex > 0 ? name.slice(0, dotIndex) : name;
  var previous;
  do {
    previous = stem;
    stem = stem.replace(/\s*\(\d+\)\s*$/, "").trim();
  } while (stem !== previous);
  return stem + extension;
}

function invalidateAnalyticsCache_() {
  try {
    var cache = CacheService.getScriptCache();
    cache.remove("PARTNER_ANALYTICS_V5");
    cache.remove("PARTNER_ANALYTICS_V6");
    cache.remove("PARTNER_ANALYTICS_V7");
  } catch (e) {}
}

// -------------------------------------------------------------------
// CATALOG SYNC ENGINE (AIRTIGHT REGEX MAPPER)
// -------------------------------------------------------------------
function getMatchKey_(filename) {
    var name = String(filename || "").trim().toLowerCase();
    name = name.replace(/\.(imscc|zip|xml|xlsx)$/, "").trim();
    var previous;
    do {
        previous = name;
        name = name.replace(/\s*\(\d+\)\s*$/, "").trim();
    } while (name !== previous);
    name = name.replace(/\s*-?\s*(dev|development)\s*\(nce\)?\s*(-?\s*clxt)?/g, "").trim();
    name = name.replace(/b0rl/g, "borl");
    name = name.replace(/[\s\-]/g, "");
    return name;
}

// v6.11 semantic package identity. Browser download suffixes, DEV (NCE), spacing
// and hyphen variants of the same title code must resolve to one saved-package
// identity. The partner remains part of every duplicate/save match, so identical
// codes for different partners never collide.
function packageSemanticKey_(fileName) {
    var key = getMatchKey_(fileName);
    if (key && key.length >= 3) return key;
    return normalizeFileName_(fileName, true);
}

function updateCatalogMapSheet_(ss, mapping) {
    var sheet = ss.getSheetByName('Catalog_Map');
    if (!sheet) {
        sheet = ss.insertSheet('Catalog_Map');
        sheet.hideSheet();
    }
    sheet.clear();
    var rows = [["Match Key", "Real Title", "Assignment Owner"]];
    for (var key in mapping) {
        rows.push([key, mapping[key].title, mapping[key].owner]);
    }
    if (rows.length > 1) {
        sheet.getRange(1, 1, rows.length, 3).setValues(rows);
    }
}

function loadCatalogMap_(ss) {
    var sheet = ss.getSheetByName('Catalog_Map');
    if (!sheet) return {};
    var data = sheet.getDataRange().getValues();
    var map = {};
    for (var i = 1; i < data.length; i++) {
        map[String(data[i][0])] = {
            title: String(data[i][1]),
            owner: String(data[i][2])
        };
    }
    return map;
}

function syncCatalogsFromDrive() {
  authorize_('editor');
  var lock = LockService.getScriptLock();
  if (!lock.tryLock(15000)) return { success: false, error: "Database busy." };
  try {
    var mapping = {};
    var naitId = "1Z7xpd4_75pyZsTp-mrxxDX03gAlw1zdQxZLeifIzwOc";
    var marshId = "16vzyWCfp7blk1TxXgNaVLGRBlQfripZGOAAJXdLauFM";
    var naitFound = false;
    var marshFound = false;

    try {
        var ssNait = SpreadsheetApp.openById(naitId);
        var sheetNait = ssNait.getSheetByName("NAIT Full Catalog 2026") || ssNait.getSheets()[0];
        var data = sheetNait.getDataRange().getValues();
        var headers = data[0].map(function(h) { return String(h).trim(); });
        var codeIdx = headers.indexOf("Title Code"), titleIdx = headers.indexOf("Title"), ownerIdx = headers.indexOf("Assignment Owner");
        if (codeIdx > -1 && titleIdx > -1) {
            for (var i = 1; i < data.length; i++) {
                var code = String(data[i][codeIdx]).trim();
                if (!code) continue;
                mapping[getMatchKey_(code)] = {
                    title: String(data[i][titleIdx]).trim(),
                    owner: ownerIdx > -1 ? String(data[i][ownerIdx]).trim() : ""
                };
            }
        }
        naitFound = true;
    } catch(e) {}

    try {
        var ssMarsh = SpreadsheetApp.openById(marshId);
        var sheetMarsh = ssMarsh.getSheetByName("Sheet1") || ssMarsh.getSheets()[0];
        var data = sheetMarsh.getDataRange().getValues();
        var headers = data[0].map(function(h) { return String(h).trim(); });
        var ccIdx = headers.indexOf("Common Cartridge File Name"), titleIdx = headers.indexOf("Title"), ownerIdx = headers.indexOf("Assignment Owner");
        if (ccIdx > -1 && titleIdx > -1) {
            for (var i = 1; i < data.length; i++) {
                var cc = String(data[i][ccIdx]).trim();
                if (!cc) continue;
                mapping[getMatchKey_(cc)] = {
                    title: String(data[i][titleIdx]).trim(),
                    owner: ownerIdx > -1 ? String(data[i][ownerIdx]).trim() : ""
                };
            }
        }
        marshFound = true;
    } catch(e) {}
    
    if (!naitFound && !marshFound) return { success: false, error: "Could not access either Catalog Sheet." };

    var dbSheet = getDatabaseSheet_();
    updateCatalogMapSheet_(dbSheet.getParent(), mapping);
    invalidateAnalyticsCache_();
    
    return { success: true, message: "Successfully synced " + Object.keys(mapping).length + " titles." };
  } catch (e) { 
      return { success: false, error: "Sync Error: " + e.message }; 
  } finally { lock.releaseLock(); }
}


// -------------------------------------------------------------------
// WORK ORCHESTRATION — live planner/catalog/SCORM assignment queue
// -------------------------------------------------------------------
function workNormalizeHeader_(value) {
  return String(value || '').toLowerCase().replace(/\s+/g, ' ').trim();
}

function workHeaderIndex_(headers, names) {
  var normalized = (headers || []).map(workNormalizeHeader_);
  for (var n = 0; n < names.length; n++) {
    var needle = workNormalizeHeader_(names[n]);
    var idx = normalized.indexOf(needle);
    if (idx > -1) return idx;
  }
  return -1;
}

function workOwnerKey_(value) {
  return String(value || '').toLowerCase().replace(/[.\s]+/g, ' ').trim();
}